-- تصحيحات مراجعة Apple (٢٠٢٦-١٠-٢٨، «صلّح الكل»): البريد ضمن ما تضيفه، بند «بيانات أقاربك»،
-- وحذف الحساب يوضّح أن الاسم والموضع يبقيان في الشجرة (مطابق لـ finalize_account_deletion).
update public.app_config set value = $j${"title": "الخصوصية والاستخدام", "subtitle": "سياسة الخصوصية وشروط الاستخدام", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "بياناتك وخصوصيتك", "items": [{"id": "collect", "title": "ما نجمعه", "lines": ["اسمك ورقم هاتفك فقط.", "تُدخل رقمك بنفسك لتسجيل الدخول، فنربطه باسمك ونحفظه على خوادمنا.", "وأي معلومات تضيفها باختيارك، مثل بريدك وقرابتك وتاريخ ميلادك وصورتك ونبذتك ومنشوراتك."]}, {"id": "relatives", "title": "بيانات أقاربك", "lines": ["حين تضيف أحد أقاربك تُحفظ بياناته التي تضيفها، كالاسم والتواريخ والصورة، وتظهر لأعضاء العائلة في الشجرة.", "أضفها بعلم صاحبها، ولك تعديلها أو حذفها متى شئت."]}, {"id": "auto", "title": "وتلقائياً", "lines": ["جهازك وآخر نشاط لك وأخطاء التطبيق، لحماية حسابك وتحسينه."]}, {"id": "why", "title": "لماذا", "lines": ["لتعمل الشجرة والأخبار والإشعارات، بلا إعلانات ولا بيع."]}, {"id": "who", "title": "من يراها", "lines": ["أعضاء العائلة في التطبيق فقط، ولك إخفاء رقمك."]}, {"id": "share", "title": "مع من نشاركها", "lines": ["لا أحد لأغراض تجارية.", "فقط مزوّدو التشغيل: الاستضافة والرسائل النصية وإشعارات Apple و Google."]}, {"id": "otp", "title": "رمز الدخول", "lines": ["رسالة نصية لمرة واحدة.", "ولحمايتك نراجع محاولات الدخول المتكررة."]}, {"id": "security", "title": "الحماية", "lines": ["اتصال مشفّر، وخوادم Supabase لحفظ البيانات."]}, {"id": "delete", "title": "حذف حسابك", "lines": ["من الإعدادات، ويتم فوراً: يُحذف حسابك وصورك وبياناتك الشخصية ومنشوراتك وتعليقاتك.", "ويبقى اسمك وموضعك في شجرة العائلة حفاظاً على تسلسل النسب."]}]}, {"key": "terms", "title": "قواعد الاستخدام", "items": [{"id": "eligibility", "title": "لمن التطبيق", "lines": ["لعائلة المحمدعلي وأقاربها."]}, {"id": "account", "title": "حسابك", "lines": ["لا تشارك رمز الدخول مع أحد."]}, {"id": "respect", "title": "لا تهاون مع الإساءة", "lines": ["لا محتوى مسيء ولا انتحال ولا نشر لبيانات الأعضاء.", "يمكنك الإبلاغ عن أي محتوى أو عضو وحظره، ونراجع كل بلاغ خلال ٢٤ ساعة."]}, {"id": "content", "title": "ما تضيفه", "lines": ["ملكك، ولنا إخفاؤه إن خالف القواعد."]}, {"id": "contact", "title": "التواصل", "lines": ["من داخل التطبيق، أو info@almohali.com"]}]}]}$j$::jsonb, default_value = $j${"title": "الخصوصية والاستخدام", "subtitle": "سياسة الخصوصية وشروط الاستخدام", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "بياناتك وخصوصيتك", "items": [{"id": "collect", "title": "ما نجمعه", "lines": ["اسمك ورقم هاتفك فقط.", "تُدخل رقمك بنفسك لتسجيل الدخول، فنربطه باسمك ونحفظه على خوادمنا.", "وأي معلومات تضيفها باختيارك، مثل بريدك وقرابتك وتاريخ ميلادك وصورتك ونبذتك ومنشوراتك."]}, {"id": "relatives", "title": "بيانات أقاربك", "lines": ["حين تضيف أحد أقاربك تُحفظ بياناته التي تضيفها، كالاسم والتواريخ والصورة، وتظهر لأعضاء العائلة في الشجرة.", "أضفها بعلم صاحبها، ولك تعديلها أو حذفها متى شئت."]}, {"id": "auto", "title": "وتلقائياً", "lines": ["جهازك وآخر نشاط لك وأخطاء التطبيق، لحماية حسابك وتحسينه."]}, {"id": "why", "title": "لماذا", "lines": ["لتعمل الشجرة والأخبار والإشعارات، بلا إعلانات ولا بيع."]}, {"id": "who", "title": "من يراها", "lines": ["أعضاء العائلة في التطبيق فقط، ولك إخفاء رقمك."]}, {"id": "share", "title": "مع من نشاركها", "lines": ["لا أحد لأغراض تجارية.", "فقط مزوّدو التشغيل: الاستضافة والرسائل النصية وإشعارات Apple و Google."]}, {"id": "otp", "title": "رمز الدخول", "lines": ["رسالة نصية لمرة واحدة.", "ولحمايتك نراجع محاولات الدخول المتكررة."]}, {"id": "security", "title": "الحماية", "lines": ["اتصال مشفّر، وخوادم Supabase لحفظ البيانات."]}, {"id": "delete", "title": "حذف حسابك", "lines": ["من الإعدادات، ويتم فوراً: يُحذف حسابك وصورك وبياناتك الشخصية ومنشوراتك وتعليقاتك.", "ويبقى اسمك وموضعك في شجرة العائلة حفاظاً على تسلسل النسب."]}]}, {"key": "terms", "title": "قواعد الاستخدام", "items": [{"id": "eligibility", "title": "لمن التطبيق", "lines": ["لعائلة المحمدعلي وأقاربها."]}, {"id": "account", "title": "حسابك", "lines": ["لا تشارك رمز الدخول مع أحد."]}, {"id": "respect", "title": "لا تهاون مع الإساءة", "lines": ["لا محتوى مسيء ولا انتحال ولا نشر لبيانات الأعضاء.", "يمكنك الإبلاغ عن أي محتوى أو عضو وحظره، ونراجع كل بلاغ خلال ٢٤ ساعة."]}, {"id": "content", "title": "ما تضيفه", "lines": ["ملكك، ولنا إخفاؤه إن خالف القواعد."]}, {"id": "contact", "title": "التواصل", "lines": ["من داخل التطبيق، أو info@almohali.com"]}]}]}$j$::jsonb where key = 'legal_content';
update public.app_config set value = $j${"title": "Privacy & Use", "subtitle": "Privacy Policy and Terms of Use", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "Your data and privacy", "items": [{"id": "collect", "title": "What we collect", "lines": ["Only your name and phone number.", "You enter your number yourself to sign in; we link it to your name and keep it on our servers.", "Plus any information you choose to add, such as your email, family links, birth date, photo, bio and posts."]}, {"id": "relatives", "title": "Your relatives' details", "lines": ["When you add a relative, the details you add, such as name, dates and photo, are saved and shown to family members in the tree.", "Add them with that person's knowledge; you can edit or remove them at any time."]}, {"id": "auto", "title": "Automatically", "lines": ["Your device, your last activity and app errors — to protect your account and improve the app."]}, {"id": "why", "title": "Why", "lines": ["To run the tree, news and notifications — no ads, never sold."]}, {"id": "who", "title": "Who sees it", "lines": ["Family members in the app only, and you can hide your number."]}, {"id": "share", "title": "Who we share it with", "lines": ["No one, for any commercial purpose.", "Only the services that run the app: hosting, text messages, and Apple and Google notifications."]}, {"id": "otp", "title": "Login code", "lines": ["A one-time text message.", "To protect you, we review repeated login attempts."]}, {"id": "security", "title": "Security", "lines": ["Encrypted connections; data is stored on Supabase servers."]}, {"id": "delete", "title": "Deleting your account", "lines": ["From Settings, immediately: your account, photos, personal details, posts and comments are deleted.", "Your name and place in the family tree remain, to keep the lineage intact."]}]}, {"key": "terms", "title": "Rules of use", "items": [{"id": "eligibility", "title": "Who it's for", "lines": ["For the Al-Mohammed Ali family and its relatives."]}, {"id": "account", "title": "Your account", "lines": ["Never share your login code."]}, {"id": "respect", "title": "Zero tolerance for abuse", "lines": ["No offensive content, impersonation or sharing members' data.", "You can report or block any content or member, and we review every report within 24 hours."]}, {"id": "content", "title": "What you add", "lines": ["It's yours, and we may hide it if it breaks the rules."]}, {"id": "contact", "title": "Contact", "lines": ["From inside the app, or info@almohali.com"]}]}]}$j$::jsonb, default_value = $j${"title": "Privacy & Use", "subtitle": "Privacy Policy and Terms of Use", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "Your data and privacy", "items": [{"id": "collect", "title": "What we collect", "lines": ["Only your name and phone number.", "You enter your number yourself to sign in; we link it to your name and keep it on our servers.", "Plus any information you choose to add, such as your email, family links, birth date, photo, bio and posts."]}, {"id": "relatives", "title": "Your relatives' details", "lines": ["When you add a relative, the details you add, such as name, dates and photo, are saved and shown to family members in the tree.", "Add them with that person's knowledge; you can edit or remove them at any time."]}, {"id": "auto", "title": "Automatically", "lines": ["Your device, your last activity and app errors — to protect your account and improve the app."]}, {"id": "why", "title": "Why", "lines": ["To run the tree, news and notifications — no ads, never sold."]}, {"id": "who", "title": "Who sees it", "lines": ["Family members in the app only, and you can hide your number."]}, {"id": "share", "title": "Who we share it with", "lines": ["No one, for any commercial purpose.", "Only the services that run the app: hosting, text messages, and Apple and Google notifications."]}, {"id": "otp", "title": "Login code", "lines": ["A one-time text message.", "To protect you, we review repeated login attempts."]}, {"id": "security", "title": "Security", "lines": ["Encrypted connections; data is stored on Supabase servers."]}, {"id": "delete", "title": "Deleting your account", "lines": ["From Settings, immediately: your account, photos, personal details, posts and comments are deleted.", "Your name and place in the family tree remain, to keep the lineage intact."]}]}, {"key": "terms", "title": "Rules of use", "items": [{"id": "eligibility", "title": "Who it's for", "lines": ["For the Al-Mohammed Ali family and its relatives."]}, {"id": "account", "title": "Your account", "lines": ["Never share your login code."]}, {"id": "respect", "title": "Zero tolerance for abuse", "lines": ["No offensive content, impersonation or sharing members' data.", "You can report or block any content or member, and we review every report within 24 hours."]}, {"id": "content", "title": "What you add", "lines": ["It's yours, and we may hide it if it breaks the rules."]}, {"id": "contact", "title": "Contact", "lines": ["From inside the app, or info@almohali.com"]}]}]}$j$::jsonb where key = 'legal_content_en';
